class Solution:
    def minCost(self, n, cost):
        # valid (left color, right color) pairs for a mirrored pair of houses
        pairs = [(a, b) for a in range(3) for b in range(3) if a != b]

        # outermost pair: houses 0 and n-1
        dp = {(a, b): cost[0][a] + cost[n - 1][b] for a, b in pairs}

        for i in range(1, n // 2):
            ndp = {}
            for a, b in pairs:
                best = min(dp[(pa, pb)] for pa, pb in pairs if pa != a and pb != b)
                ndp[(a, b)] = best + cost[i][a] + cost[n - 1 - i][b]
            dp = ndp

        return min(dp.values())
